function videoGenerationDevice(){const d=localStorage.getItem('frame-video-device');return ['remote','lightcc'].includes(d)?d:'local';}
function videoGenerationPort(){if(videoGenerationDevice()==='lightcc')return 18191;if(videoGenerationDevice()==='remote')return 18188;const n=Number(localStorage.getItem('frame-comfy-port')||8188);return [18188,18191].includes(n)?8188:n;}
