 async function refreshSelectedServerStatus(){const el=document.getElementById('selectedCloudServerStatus');if(!el)return;const key=el.dataset.selectionId||'';if(selectedStatusCache&&selectedStatusKey===key){el.textContent=serverStatusText(selectedStatusCache);if(Date.now()-selectedStatusAt<10000)return}if(selectedStatusBusy)return;selectedStatusBusy=true;try{const j=await cloudCall('/selected-instance').catch(async()=>{const [runtime,all,current]=await Promise.all([cloudCall('/runtime'),cloudCall('/instances'),cloudCall('/selection')]);const instance=all.instances?.find(x=>String(x.id)===String(runtime.applicationId)&&x.gpu===current.selection?.gpu);const labels={'0':'租用中 · 创建部署中','1':'运行中','2':'已关机','3':'开机中','4':'关机中','5':'状态未知','6':'已销毁','7':'异常','8':'重启中'};return {status:instance?.status,startTime:instance?.startTime,label:instance?(labels[String(instance.status)]||'状态未知'):'实例状态待确认'}});selectedStatusCache=j;selectedStatusAt=Date.now();selectedStatusKey=key;const current=document.getElementById('selectedCloudServerStatus');if(current?.dataset.selectionId===key){current.textContent=serverStatusText(j);current.title='服务器状态 · '+new Date().toLocaleTimeString('zh-CN',{hour12:false})}}catch{if(el.isConnected)el.textContent=' · 状态读取失败'}finally{selectedStatusBusy=false}} async function cloudCall(route,body){const r=await fetch('/api/lightcc'+route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(45000)});const j=await r.json();if(!r.ok)throw Error(j.error||'读取云配置失败');return j}
